<?php require_once "../config/auth.php";$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$u=trim($_POST["username"]??"");$em=trim($_POST["email"]??"");$p=$_POST["password"]??"";$cp=$_POST["confirm"]??"";if(!preg_match("/^[A-Za-z0-9_]{3,30}$/",$u))$err="Invalid username.";elseif(!filter_var($em,FILTER_VALIDATE_EMAIL))$err="Invalid email.";elseif(strlen($p)<8)$err="Password must be at least 8 characters.";elseif($p!==$cp)$err="Passwords do not match.";else{$q=db()->prepare("SELECT id FROM users WHERE username=? OR email=?");$q->execute([$u,$em]);if($q->fetch())$err="Username or email already exists.";else{$q=db()->prepare("INSERT INTO users(username,email,password_hash) VALUES(?,?,?)");$q->execute([$u,$em,password_hash($p,PASSWORD_DEFAULT)]);header("Location: login.php?registered=1");exit;}}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body class="auth"><form class="box" method="post"><h1>NEXORA <span>SMM</span></h1><h2>Create Account</h2><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="username" placeholder="Username" required><input name="email" type="email" placeholder="Email" required><input name="password" type="password" placeholder="Password (8+)" required><input name="confirm" type="password" placeholder="Confirm Password" required><button>Register</button><p>Already have an account? <a href="login.php">Login</a></p></form></body></html>